const SyscallMetadata* lookup(std::uint16_t number) noexcept {
    // Entries are sorted; binary search keeps lookup bounded.
    std::size_t lo = 0, hi = sizeof(table) / sizeof(table[0]);
    while (lo < hi) { const std::size_t mid = lo + (hi - lo) / 2;
        if (table[mid].number == number) return &table[mid];
        if (table[mid].number < number) lo = mid + 1; else hi = mid;
    }
    return nullptr;
}
std::size_t count() noexcept { return sizeof(table) / sizeof(table[0]); }
